#include "ecophon.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){Eco a,b,c;int16_t x[240],y[240],z[240];unsigned dif=0,nonzero=0;eco_reset(&a,42,0);eco_reset(&b,42,0);eco_reset(&c,42,0);eco_controls(&c,c.fertility,c.sharing,c.pressure,1);for(unsigned t=0;t<12000;++t){eco_render(&a,x,240);eco_render(&b,y,17);eco_render(&b,y+17,223);eco_render(&c,z,240);assert(!memcmp(x,y,sizeof x));assert(!memcmp(&a,&b,sizeof a));for(unsigned j=0;j<240;++j){assert(x[j]>=-24000&&x[j]<=24000);dif+=x[j]!=z[j];nonzero+=x[j]!=0;}for(unsigned j=0;j<ECO_AGENTS;++j){assert(a.a[j].energy<=ECO_CAP);assert(a.a[j].envelope<=3000);}for(unsigned j=0;j<ECO_PATCHES;++j)assert(a.resource[j]<=ECO_CAP);}assert(dif>10000&&nonzero>10000);assert(a.births&&a.gifts&&a.moves&&a.consumed);assert(c.births==0&&c.gifts==0&&c.moves==0&&c.consumed==0);printf("12000 ticks; births=%u deaths=%u gifts=%u moves=%u consumed=%u; ablation differences=%u; state=%zu bytes\n",a.births,a.deaths,a.gifts,a.moves,a.consumed,dif,sizeof a);eco_mute(&a,1);eco_render(&a,x,240);for(unsigned j=0;j<240;++j)assert(!x[j]);eco_reset(&a,42,0);eco_reset(&b,42,0);eco_render(&a,x,240);eco_render(&b,y,240);assert(!memcmp(x,y,sizeof x));eco_controls(&a,999,999,999,1);assert(a.fertility==255&&a.sharing==255&&a.pressure==255);eco_controls(&a,0,0,255,0);for(unsigned t=0;t<1000;++t)eco_render(&a,x,240);assert(a.deaths);puts("PASS deterministic partition, ablation, reset, mute, bounds, pressure death");}
